package com.argument.integration;
import com.argument.version.*;
import com.argument.version.local.*;
import com.argument.membera.store.WorkflowStore;
import com.argument.security.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.SpyBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
class UnifiedWorkflowIntegrationTest {
 @Autowired MockMvc mvc;@Autowired ObjectMapper mapper;@Autowired JdbcTemplate jdbc;@Autowired LocalFixtureLoader fixtures;@Autowired LocalAccountLoader accounts;@Autowired LocalAnnotationDependencies data;@Autowired WorkflowStore aStore;@Autowired UnifiedVersionIdentity identity;@Autowired VersionService versions;@Autowired SharedSnapshotReader reader;
 @SpyBean WorkflowCommandHistory history;
 static final String TASK="f102c523-b4ed-4323-81d3-0c564c4141a0",CASE="3cbb140f-0274-4871-8248-194271101a14",DRAFT="f67848e1-a06d-4600-8454-19055e720d2c";
 @BeforeEach void setup()throws Exception{reset(history);clean();fixtures.run(null);accounts.run(null);}
 @AfterEach void after(){reset(history);clean();}
 void clean(){for(String t:List.of("workflow_command_history","trial_correction_rounds","trial_segmentation_records","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","snapshot_object_owners","annotation_version_snapshots","annotation_versions","annotation_case_counters","workflow_records"))jdbc.update("DELETE FROM "+t);}
 String login(String name)throws Exception{var r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/auth/login").contentType("application/json").content(mapper.createObjectNode().put("username",name).put("password","demo").toString())).andReturn().getResponse();assertThat(r.getStatus()).isEqualTo(200);return mapper.readTree(r.getContentAsString()).path("data").path("token").asText();}
 ObjectNode validBinding(){var cmd=mapper.createObjectNode().put("requiredAnnotators",2);var source=data.read("taskDocument",CASE);for(String f:List.of("documentId","documentTextVersionId","annotationScopeId"))cmd.set(f,source.get(f));return cmd;}
 ObjectNode createCommand(){var n=mapper.createObjectNode().put("name","联合数据任务").put("guideVersionId",data.read("task",TASK).path("guideVersionId").asText()).put("taskType","FORMAL_RESEARCH").put("defaultRequiredAnnotators",2).put("autoPreannotationEnabled",false).put("expertConfirmationRequired",false).put("adjudicationReasonRequired",true);return n;}
 ObjectNode postCommand(String url,String token,String key,ObjectNode body,int expected)throws Exception{var r=mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(url).header("Authorization","Bearer "+token).header("Idempotency-Key",key).contentType("application/json").content(body.toString())).andReturn().getResponse();assertThat(r.getStatus()).as(r.getContentAsString()).isEqualTo(expected);return (ObjectNode)mapper.readTree(r.getContentAsString());}
 @Test void actualLoginRestoresCanonicalIdentityAndLogoutRevokesToken()throws Exception{String token=login("creator.li");var r=mvc.perform(get("/api/v1/auth/me").header("Authorization","Bearer "+token)).andReturn().getResponse();var user=mapper.readTree(r.getContentAsString()).path("data");assertThat(user.path("id").asText()).isEqualTo("9795b546-9838-4ef5-ab05-4ba73d88ea7e");assertThat(user.path("username").asText()).isEqualTo("creator.li");assertThat(user.path("roles").toString()).contains("creator");assertThat(r.getContentAsString()).doesNotContain("password");postCommand("/api/v1/auth/logout",token,VersionJson.uuid(),mapper.createObjectNode(),200);assertThat(mvc.perform(get("/api/v1/tasks").header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus()).isEqualTo(401);}
 @Test void aCreatesPersistentTaskAndDImmediatelyReadsItsProgress()throws Exception{String token=login("creator.li"),key=VersionJson.uuid();var command=createCommand();var created=postCommand("/api/v1/tasks",token,key,command,200);String id=created.path("data").path("id").asText();assertThat(postCommand("/api/v1/tasks",token,key,command,200).path("data")).isEqualTo(created.path("data"));assertThat(data.read("task",id).path("name").asText()).isEqualTo("联合数据任务");assertThat(aStore.tasks.get(id).get("id")).isEqualTo(id);assertThat(mvc.perform(get("/api/v1/tasks/"+id+"/progress").header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus()).isEqualTo(200);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM workflow_command_history",Integer.class)).isEqualTo(1);postCommand("/api/v1/tasks",token,key,command.put("name","不同内容"),409);}
 @Test void aBindsActualTextAndDSeesExactlyTheSameCase()throws Exception{String token=login("creator.li");String id=postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand(),200).path("data").path("id").asText();var source=data.read("taskDocument",CASE);var cmd=mapper.createObjectNode().put("requiredAnnotators",2);for(String f:List.of("documentId","documentTextVersionId","annotationScopeId"))cmd.set(f,source.get(f));String caseId=postCommand("/api/v1/tasks/"+id+"/documents",token,VersionJson.uuid(),cmd,200).path("data").path("id").asText();var progress=versions.progress(identity.authenticate("Bearer "+token),id);assertThat(progress.path("items").get(0).path("taskDocumentId").asText()).isEqualTo(caseId);assertThat(aStore.taskDocuments.get(caseId).get("documentTextVersionId")).isEqualTo(source.path("documentTextVersionId").asText());}
 @Test void spoofedIdentityAndWrongRoleNeverCreateATask()throws Exception{assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/tasks").header("X-User-Id","9795b546-9838-4ef5-ab05-4ba73d88ea7e").contentType("application/json").content(createCommand().toString())).andReturn().getResponse().getStatus()).isEqualTo(401);postCommand("/api/v1/tasks",login("annotator.chen"),VersionJson.uuid(),createCommand(),403);postCommand("/api/v1/tasks",login("admin.wang"),VersionJson.uuid(),createCommand(),403);}
 @Test void historyFailureRollsBackTaskOwnerAndReceipt()throws Exception{String token=login("creator.li");int tasks=data.find("task",null,null).size(),members=data.find("member",null,null).size();doThrow(new IllegalStateException("test journal failure")).when(history).append(anyString(),anyString(),any(),any());postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand(),500);assertThat(data.find("task",null,null)).hasSize(tasks);assertThat(data.find("member",null,null)).hasSize(members);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM annotation_mutation_receipts",Integer.class)).isZero();}
 @Test void currentAccountStateAndSourceOwnershipAreRechecked()throws Exception{String token=login("creator.li"),key=VersionJson.uuid();var cmd=createCommand();String id=postCommand("/api/v1/tasks",token,key,cmd,200).path("data").path("id").asText();var task=data.read("task",id).put("ownerUserId",VersionJson.uuid());data.replace("task",task);postCommand("/api/v1/tasks/"+id+"/documents",token,VersionJson.uuid(),validBinding(),403);var user=data.read("user",identity.authenticate("Bearer "+token).id()).put("status","INACTIVE");data.replace("user",user);assertThat(mvc.perform(get("/api/v1/tasks").header("Authorization","Bearer "+token)).andReturn().getResponse().getStatus()).isEqualTo(401);}
 @Test void sharedSnapshotReaderPreservesBlindIsolationAndFrozenIdentity()throws Exception{var chen=identity.authenticate("Bearer "+login("annotator.chen"));var liu=identity.authenticate("Bearer "+login("annotator.liu"));assertThat(reader.read(chen,"DRAFT",DRAFT).path("draft").path("id").asText()).isEqualTo(DRAFT);assertThatThrownBy(()->reader.read(liu,"DRAFT",DRAFT)).isInstanceOf(com.argument.common.exception.BusinessException.class);var version=versions.submit(chen,DRAFT,VersionJson.uuid(),1,true,"");var snapshot=reader.read(chen,"ANNOTATION_VERSION",version.path("id").asText());assertThat(snapshot.path("version").path("id")).isEqualTo(version.get("id"));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM snapshot_object_owners WHERE owner_id=?",Integer.class,version.path("id").asText())).isGreaterThan(0);assertThatThrownBy(()->reader.read(liu,"ANNOTATION_VERSION",version.path("id").asText())).isInstanceOf(com.argument.common.exception.BusinessException.class);}
 @Test void strictFrozenTaskCommandsRejectSpoofedFields()throws Exception{String token=login("creator.li");postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand().put("ownerUserId",VersionJson.uuid()),400);postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand().put("defaultRequiredAnnotators",1),400);}
 @Test void unpublishedGuideCannotBeUsedEvenIfItsIdWasInOldMockAllowlist()throws Exception{String token=login("creator.li");String guide=createCommand().path("guideVersionId").asText();data.replace("guideVersion",data.read("guideVersion",guide).put("status","DRAFT"));postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand(),409);}
 @Test void optionsAreRealAuthorizedResourcesAndBindingReplayRechecksOwnership()throws Exception{String token=login("creator.li");var r=mvc.perform(get("/api/v1/integration/task-options").header("Authorization","Bearer "+token)).andReturn().getResponse();assertThat(r.getStatus()).isEqualTo(200);var options=mapper.readTree(r.getContentAsString()).path("data");assertThat(options.path("guides").get(0).path("id").asText()).isEqualTo(createCommand().path("guideVersionId").asText());for(var guide:options.path("guides"))assertThatCode(()->VersionJson.uuid(guide.path("id").asText())).doesNotThrowAnyException();assertThat(options.path("documents")).isNotEmpty();String id=postCommand("/api/v1/tasks",token,VersionJson.uuid(),createCommand(),200).path("data").path("id").asText(),key=VersionJson.uuid();postCommand("/api/v1/tasks/"+id+"/documents",token,key,validBinding(),200);data.replace("task",data.read("task",id).put("ownerUserId",VersionJson.uuid()));postCommand("/api/v1/tasks/"+id+"/documents",token,key,validBinding(),403);assertThat(mvc.perform(get("/api/v1/integration/task-options").header("Authorization","Bearer "+login("annotator.chen"))).andReturn().getResponse().getStatus()).isEqualTo(403);}
 @Test void inactiveOriginalAssignmentCannotReadDraftThroughAnotherActiveAssignment()throws Exception{var actor=identity.authenticate("Bearer "+login("annotator.chen"));var draft=data.read("draft",DRAFT);var old=data.read("assignment",draft.path("assignmentId").asText());var replacement=old.deepCopy().put("id",VersionJson.uuid());jdbc.update("INSERT INTO workflow_records VALUES('assignment',?,?)",replacement.path("id").asText(),replacement.toString());data.replace("assignment",old.put("status","INACTIVE"));assertThat(versions.hasAssignment(actor,CASE,"ANNOTATOR")).isTrue();assertThatThrownBy(()->reader.read(actor,"DRAFT",DRAFT)).isInstanceOf(com.argument.common.exception.BusinessException.class);}

 @Test void missingIdempotencyHeaderIsAClientErrorAndDoesNotWrite()throws Exception{String token=login("creator.li");int before=data.find("task",null,null).size();assertThat(mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/api/v1/tasks").header("Authorization","Bearer "+token).contentType("application/json").content(createCommand().toString())).andReturn().getResponse().getStatus()).isEqualTo(400);assertThat(data.find("task",null,null)).hasSize(before);}
 @Test void reassigningPreservesInactiveOriginalRecordsAndRejectsStaleCaseVersion()throws Exception{String token=login("creator.li");data.replace("task",data.read("task",TASK).put("status","DRAFT"));var old=data.find("assignment","taskDocumentId",CASE);var cmd=mapper.createObjectNode();var annotators=cmd.putArray("annotatorMemberIds");for(var a:old)if("ANNOTATOR".equals(a.path("assignmentRole").asText()))annotators.add(a.path("taskMemberId").asText());else if("ARBITER".equals(a.path("assignmentRole").asText()))cmd.put("arbiterMemberId",a.path("taskMemberId").asText());int version=data.read("taskDocument",CASE).path("recordVersion").asInt();var request=put("/api/v1/task-documents/"+CASE+"/assignments").header("Authorization","Bearer "+token).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",version).contentType("application/json").content(cmd.toString());var response=mvc.perform(request).andReturn().getResponse();assertThat(response.getStatus()).as(response.getContentAsString()).isEqualTo(200);for(var a:old)assertThat(data.read("assignment",a.path("id").asText()).path("status").asText()).isEqualTo("INACTIVE");assertThat(data.find("assignment","taskDocumentId",CASE)).hasSize(old.size()*2);assertThat(mvc.perform(put("/api/v1/task-documents/"+CASE+"/assignments").header("Authorization","Bearer "+token).header("Idempotency-Key",VersionJson.uuid()).header("If-Match",version).contentType("application/json").content(cmd.toString())).andReturn().getResponse().getStatus()).isEqualTo(409);assertThat(data.find("assignment","taskDocumentId",CASE)).hasSize(old.size()*2);}

 @Test void corsPreflightUsesConfiguredOriginsWithoutRequiringLogin()throws Exception{var allowed=mvc.perform(options("/api/v1/tasks").header("Origin","http://127.0.0.1:5174").header("Access-Control-Request-Method","POST").header("Access-Control-Request-Headers","authorization,content-type,idempotency-key")).andReturn().getResponse();assertThat(allowed.getStatus()).isEqualTo(200);assertThat(allowed.getHeader("Access-Control-Allow-Origin")).isEqualTo("http://127.0.0.1:5174");assertThat(mvc.perform(options("/api/v1/tasks").header("Origin","https://untrusted.invalid").header("Access-Control-Request-Method","POST")).andReturn().getResponse().getStatus()).isEqualTo(403);}

 @Test void legacyGuideWritesRequireCurrentGuidePermission()throws Exception{postCommand("/api/v1/guides",login("annotator.chen"),VersionJson.uuid(),mapper.createObjectNode(),403);String adminToken=login("admin.wang");postCommand("/api/v1/guides",adminToken,VersionJson.uuid(),mapper.createObjectNode(),400);var admin=data.read("user",identity.authenticate("Bearer "+adminToken).id());for(var id:admin.path("roleIds")){var role=data.read("role",id.asText());var permissions=role.putArray("permissionCodes");permissions.add("GUIDE_VIEW");data.replace("role",role);}postCommand("/api/v1/guides",adminToken,VersionJson.uuid(),mapper.createObjectNode(),403);}

}
